-- =============================================================================
-- NEXA · 4910 · News battles: four more round games (ADR-160, addendum)
-- =============================================================================
-- Tresorknacker (vault), Ticker-Tippen (ticker), Mehr oder Weniger (higher) and Wer bietet mehr? (auction), judged
-- on the server like Börsenquiz (src/lib/sim/battle/rounds-more.ts is the same judging for the demo and the tests):
-- * vault: the codes stay in battles.plan; every try goes through battle_answer (p_choice = the digits, e.g. 352)
--   into battle_guesses, the server answers with how many digits are in place and how many elsewhere. Cracked =
--   a row in battle_answers (choice = tries). At most maxTries tries, nothing after cracking.
-- * ticker: like the quiz with `options` tickers (listed stocks, else battles.tickers); a wrong tap costs points.
-- * higher: a chart with trends (battles.plan.series, prices in cents); choice 0 higher, 1 lower; hearts as in the
--   bell. The client sees the chart only up to the current candle, the next one after the round closed.
-- * auction: sealed bids (p_value, whole play money, at most what is left: the server checks); the highest bid wins
--   the item's points and pays it. Bids are shown after the gavel.
-- Patched by replace (other migrations may patch the same functions): battle_plan, battle_round_ms,
-- battle_rounds_eval, battle_rounds_json, battle_answer. New: battle_plan_more, battle_rounds_eval_more,
-- battle_round_extra, battle_answer_more, table battle_guesses.
-- Round JSON adds: vault {"digits", "symbols", "guesses": [{"code", "hits", "near"}] (own), "progress": [{"slot",
-- "tries", "cracked"}], "code" (after the round)}; higher {"chart": [price, ...]}; auction {"item_points", "icon",
-- "budget" (own), "budgets": [per slot]}.
-- Idempotent: runs unchanged as supabase/updates/20261204004910_more_battle_games.sql.

-- ---------------------------------------------------------------------------
-- A. The tries of Tresorknacker
-- ---------------------------------------------------------------------------
create table if not exists public.battle_guesses (
  battle_id  bigint not null references public.battles (id) on delete cascade,
  round      smallint not null check (round between 0 and 99),
  player_id  uuid not null references public.profiles (id) on delete cascade,
  n          smallint not null check (n between 1 and 99),
  code       text not null check (code ~ '^[1-9]{1,9}$'),
  hits       smallint not null,
  near       smallint not null,
  guessed_at timestamptz not null,
  primary key (battle_id, round, player_id, n)
);
alter table public.battle_guesses enable row level security;
revoke all on public.battle_guesses from public, anon, authenticated;
create index if not exists battle_guesses_player_idx on public.battle_guesses (player_id);
comment on table public.battle_guesses is
  'Tries in Tresorknacker (news battles, ADR-160) with the server''s answer (hits in place, near elsewhere) and the '
  'server time. Internal; the code stays in battles.plan.';

-- ---------------------------------------------------------------------------
-- B. Plans: codes, tickers, the chart, the items
-- ---------------------------------------------------------------------------
create or replace function public.battle_plan_more(p_kind text, p_params jsonb)
returns jsonb
language plpgsql
volatile
security definer
set search_path = ''
as $$
declare
  cfg      jsonb := public.battles_cfg();
  g        jsonb := p_params -> 'game';
  v_rounds integer := (g ->> 'rounds')::integer;
  v_list   jsonb := '[]'::jsonb;
  v_pool   jsonb;
  v_opts   jsonb;
  v_target jsonb;
  v_code   text;
  v_series integer[];
  v_dir    integer;
  v_bps    integer;
  v_move   integer;
  v_next   integer;
  v_hist   integer;
  v_name   text;
  q        jsonb;
  r        integer;
begin
  if p_kind = 'vault' then
    for r in 1 .. v_rounds loop
      select string_agg(z.d::text, '' order by z.o) into v_code
        from (select d, random() as o from generate_series(1, (g ->> 'symbols')::integer) d
               order by 2 limit (g ->> 'digits')::integer) z;
      v_list := v_list || jsonb_build_array(jsonb_build_object('q', 'Tresor ' || r, 'code', v_code));
    end loop;
    return jsonb_build_object('questions', v_list);
  elsif p_kind = 'ticker' then
    select jsonb_agg(jsonb_build_object('ticker', s.ticker, 'name', s.name) order by s.o) into v_pool
      from (select sec.ticker, sec.name, random() as o from public.securities sec
             where sec.kind = 'stock' and sec.status = 'listed' and sec.ticker is not null and sec.name is not null) s;
    if coalesce(jsonb_array_length(v_pool), 0) < (g ->> 'options')::integer + v_rounds then
      select jsonb_agg(x order by random()) into v_pool from jsonb_array_elements(cfg -> 'tickers') x;
    end if;
    for r in 0 .. v_rounds - 1 loop
      v_target := v_pool -> (r % jsonb_array_length(v_pool));
      select jsonb_agg(z.t order by random()) into v_opts
        from (select v_target ->> 'ticker' as t
              union all
              (select y ->> 'ticker' from jsonb_array_elements(v_pool) y
                where y ->> 'ticker' <> v_target ->> 'ticker' order by random() limit (g ->> 'options')::integer - 1)) z;
      v_list := v_list || jsonb_build_array(jsonb_build_object(
        'q', v_target ->> 'name', 'options', v_opts,
        'correct', (select (i - 1)::integer from jsonb_array_elements_text(v_opts) with ordinality o(t, i)
                     where t = v_target ->> 'ticker' limit 1)));
    end loop;
    return jsonb_build_object('questions', v_list);
  elsif p_kind = 'higher' then
    -- a chart with trends (higherSeries in rounds-more.ts): a move goes on with trendPct %, never flat
    v_hist := (g ->> 'history')::integer;
    v_series := array[5000 + floor(random() * 15001)::integer];
    v_dir := case when random() < 0.5 then 1 else -1 end;
    while cardinality(v_series) < v_hist + v_rounds + 1 loop
      if random() * 100 >= (g ->> 'trendPct')::integer then v_dir := -v_dir; end if;
      v_bps := (g ->> 'moveMinBps')::integer
               + floor(random() * ((g ->> 'moveMaxBps')::integer - (g ->> 'moveMinBps')::integer + 1))::integer;
      v_move := greatest(1, round(v_series[cardinality(v_series)] * v_bps / 10000.0)::integer);
      v_next := v_series[cardinality(v_series)] + v_dir * v_move;
      if v_next < 100 then
        v_dir := 1;
        v_next := v_series[cardinality(v_series)] + v_move;
      end if;
      v_series := v_series || v_next;
    end loop;
    select sec.name into v_name from public.securities sec where sec.kind = 'stock' and sec.status = 'listed'
     order by random() limit 1;
    v_name := coalesce(v_name, 'NEXA-Index');
    for r in 0 .. v_rounds - 1 loop
      v_list := v_list || jsonb_build_array(jsonb_build_object(
        'q', v_name,
        'correct', case when v_series[v_hist + r + 2] > v_series[v_hist + r + 1] then 0 else 1 end,
        'value', round(v_series[v_hist + r + 2] / 100.0, 2), 'unit', '€', 'decimals', 2));
    end loop;
    return jsonb_build_object('questions', v_list, 'series', to_jsonb(v_series));
  elsif p_kind = 'auction' then
    for q in select x from jsonb_array_elements(cfg -> 'auctionItems') x order by random() limit v_rounds loop
      v_list := v_list || jsonb_build_array(jsonb_build_object('q', q ->> 'name', 'points', (q ->> 'points')::integer,
                                                               'icon', q ->> 'icon'));
    end loop;
    return jsonb_build_object('questions', v_list);
  end if;
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------------------
-- C. Judging (vaultEval, tickerEval, higherEval, auctionEval in rounds-more.ts)
-- ---------------------------------------------------------------------------
-- {"closed", "hearts", "points", "time", "out", "results", "done", "finish_ms", "ranking", "budget"}
create or replace function public.battle_rounds_eval_more(p_battle public.battles, p_now timestamptz)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  g        jsonb := p_battle.params -> 'game';
  v_kind   text := p_battle.kind;
  v_ms     bigint := public.battle_ms(p_battle.started_at, p_now);
  v_answer integer := (g ->> 'answerMs')::integer;
  n        integer;
  v_rounds integer;
  v_closed integer := 0;
  v_hearts integer;
  hearts integer[]; points integer[]; times bigint[]; outr integer[]; lft integer[]; budget integer[];
  v_alive  integer[];
  v_losers integer[];
  v_res    jsonb := '[]'::jsonb;
  v_ans    jsonb;
  v_lost   integer[];
  v_done   boolean := false;
  v_last   integer := -1;
  v_finish bigint;
  t        integer[];
  r integer; i integer; k integer;
  a        record;
  v_right  boolean;
  v_pts    integer;
  v_code   text;
  v_tries  integer;
  v_crack  integer;
  v_cms    bigint;
  v_lms    bigint;
  v_first  boolean;
  v_items  integer;
  k1 integer[]; k2 integer[]; k3 integer[];
begin
  select count(*)::integer into n from public.battle_players p where p.battle_id = p_battle.id and p.slot is not null;
  v_rounds := least((g ->> 'rounds')::integer, coalesce(jsonb_array_length(p_battle.plan -> 'questions'), 0));
  v_hearts := case when v_kind = 'higher'
                   then case when n <= (g ->> 'smallGroup')::integer then (g ->> 'heartsSmall')::integer
                             else (g ->> 'heartsLarge')::integer end
                   else 1 end;
  hearts := array_fill(v_hearts, array[greatest(n, 1)]);
  points := array_fill(0, array[greatest(n, 1)]);
  times := array_fill(0::bigint, array[greatest(n, 1)]);
  outr := array_fill(-1, array[greatest(n, 1)]);
  lft := array_fill(-1, array[greatest(n, 1)]);
  budget := array_fill(coalesce((g ->> 'budget')::integer, 0), array[greatest(n, 1)]);
  -- the round a player left in
  for a in select p.slot, p.left_at from public.battle_players p
            where p.battle_id = p_battle.id and p.slot is not null and p.left_at is not null loop
    k := 0;
    while k < v_rounds - 1 and public.battle_ms(p_battle.started_at, a.left_at) >= (public.battle_round_ms(p_battle, k))[3] loop
      k := k + 1;
    end loop;
    lft[a.slot + 1] := k;
  end loop;
  while v_closed < v_rounds and v_ms >= (public.battle_round_ms(p_battle, v_closed))[2] loop
    v_closed := v_closed + 1;
  end loop;
  r := 0;
  while r < v_closed and not v_done loop
    t := public.battle_round_ms(p_battle, r);
    for i in 1 .. n loop
      if outr[i] < 0 and lft[i] >= 0 and lft[i] <= r then outr[i] := r; end if;
    end loop;
    v_alive := '{}';
    for i in 1 .. n loop
      if outr[i] < 0 then v_alive := v_alive || i; end if;
    end loop;
    v_losers := '{}';
    v_ans := '[]'::jsonb;
    v_lost := '{}';
    if v_kind = 'vault' then
      v_code := p_battle.plan -> 'questions' -> r ->> 'code';
      foreach i in array v_alive loop
        select count(*)::integer, min(z.n) filter (where z.code = v_code), max(z.ms)
          into v_tries, v_crack, v_lms
          from (select x.n, x.code, public.battle_ms(p_battle.started_at, x.guessed_at) - t[1] as ms
                  from public.battle_guesses x join public.battle_players p on p.battle_id = x.battle_id and p.player_id = x.player_id
                 where x.battle_id = p_battle.id and x.round = r and p.slot = i - 1
                 order by x.n limit (g ->> 'maxTries')::integer) z;
        v_cms := null;
        if v_crack is not null then
          select public.battle_ms(p_battle.started_at, x.guessed_at) - t[1] into v_cms
            from public.battle_guesses x join public.battle_players p on p.battle_id = x.battle_id and p.player_id = x.player_id
           where x.battle_id = p_battle.id and x.round = r and p.slot = i - 1 and x.n = v_crack;
        end if;
        v_pts := case when v_cms is not null
                      then (g ->> 'basePoints')::integer
                           + ((g ->> 'speedPoints')::integer * greatest(0, least(v_answer, v_answer - v_cms))) / v_answer
                           + (g ->> 'tryBonus')::integer * greatest(0, (g ->> 'maxTries')::integer - v_crack)
                      else 0 end;
        points[i] := points[i] + v_pts;
        times[i] := times[i] + case when v_cms is not null then least(v_answer, greatest(0, v_cms)) else v_answer end;
        if v_tries > 0 then
          v_ans := v_ans || jsonb_build_array(jsonb_build_object('slot', i - 1, 'choice', coalesce(v_crack, v_tries),
            'ms', coalesce(v_cms, v_lms), 'points', v_pts, 'right', v_cms is not null));
        end if;
      end loop;
    elsif v_kind in ('ticker', 'higher') then
      foreach i in array v_alive loop
        select x.choice, public.battle_ms(p_battle.started_at, x.answered_at) - t[1] as ms into a
          from public.battle_answers x join public.battle_players p on p.battle_id = x.battle_id and p.player_id = x.player_id
         where x.battle_id = p_battle.id and x.round = r and p.slot = i - 1 and x.answered_at is not null;
        v_right := a.ms is not null and a.choice = (p_battle.plan -> 'questions' -> r ->> 'correct')::integer;
        v_pts := case when v_right
                      then (g ->> 'basePoints')::integer
                           + ((g ->> 'speedPoints')::integer * greatest(0, least(v_answer, v_answer - a.ms))) / v_answer
                      when v_kind = 'ticker' and a.ms is not null then -(g ->> 'wrongPoints')::integer
                      else 0 end;
        points[i] := points[i] + v_pts;
        if v_kind = 'ticker' then
          times[i] := times[i] + case when v_right then least(v_answer, greatest(0, a.ms)) else v_answer end;
        else
          times[i] := times[i] + case when a.ms is not null then least(v_answer, greatest(0, a.ms)) else v_answer end;
        end if;
        if a.ms is not null then
          v_ans := v_ans || jsonb_build_array(jsonb_build_object('slot', i - 1, 'choice', a.choice, 'ms', a.ms,
                                                                 'points', v_pts, 'right', v_right));
        end if;
        if not v_right then v_losers := v_losers || i; end if;
      end loop;
      -- hearts in Mehr oder Weniger (not when that would be everyone still in)
      if v_kind = 'higher' and cardinality(v_losers) > 0 and cardinality(v_losers) < cardinality(v_alive) then
        foreach i in array v_losers loop
          hearts[i] := hearts[i] - 1;
          if hearts[i] <= 0 then outr[i] := r; end if;
          v_lost := v_lost || (i - 1);
        end loop;
      end if;
    else
      -- the auction: the highest bid above zero wins (then the earlier one, then the lot)
      v_items := (p_battle.plan -> 'questions' -> r ->> 'points')::integer;
      v_first := true;
      for a in
        select p.slot, (x.value_e4 / 10000)::integer as bid, public.battle_ms(p_battle.started_at, x.answered_at) - t[1] as ms
          from public.battle_answers x join public.battle_players p on p.battle_id = x.battle_id and p.player_id = x.player_id
         where x.battle_id = p_battle.id and x.round = r and x.value_e4 is not null and x.answered_at is not null
           and p.slot + 1 = any (v_alive) and x.value_e4 >= 0 and x.value_e4 / 10000 <= budget[p.slot + 1]
         order by x.value_e4 desc, 3, public.battle_hash(p_battle.seed, 999, p.slot)
      loop
        v_right := v_first and a.bid > 0;
        v_first := false;
        if v_right then
          points[a.slot + 1] := points[a.slot + 1] + v_items;
          budget[a.slot + 1] := budget[a.slot + 1] - a.bid;
        end if;
        times[a.slot + 1] := times[a.slot + 1] + least(v_answer, greatest(0, a.ms));
        v_ans := v_ans || jsonb_build_array(jsonb_build_object('slot', a.slot, 'value', a.bid, 'ms', a.ms,
                                                               'points', case when v_right then v_items else 0 end,
                                                               'right', v_right));
      end loop;
    end if;
    v_res := v_res || jsonb_build_array(jsonb_build_object('round', r, 'answers', v_ans, 'lost', to_jsonb(v_lost)));
    v_last := r;
    if (select count(*) from unnest(outr) o where o < 0) <= 1 or r = v_rounds - 1 then v_done := true; end if;
    r := r + 1;
  end loop;
  if n > 0 and (select count(*) from unnest(outr) o where o < 0) <= 1 then v_done := true; end if;
  v_finish := case when v_last >= 0 then (public.battle_round_ms(p_battle, v_last))[3] else 0 end;
  k1 := array_fill(0, array[greatest(n, 1)]); k2 := k1; k3 := k1;
  for i in 1 .. n loop
    if v_kind = 'higher' then
      k1[i] := case when outr[i] < 0 then 1000000 else outr[i] end;
      k2[i] := hearts[i] * 1000000 + points[i];
    elsif v_kind = 'auction' then
      k1[i] := case when outr[i] < 0 then 1 else 0 end;
      k2[i] := points[i] * 10000 + budget[i];
    else
      k1[i] := case when outr[i] < 0 then 1 else 0 end;
      k2[i] := points[i];
    end if;
    k3[i] := -least(times[i], 2000000000)::integer;
  end loop;
  return jsonb_build_object('closed', v_closed, 'hearts', to_jsonb(hearts[1:n]), 'points', to_jsonb(points[1:n]),
                            'time', to_jsonb(times[1:n]), 'out', to_jsonb(outr[1:n]), 'results', v_res, 'done', v_done,
                            'finish_ms', v_finish, 'budget', to_jsonb(budget[1:n]),
                            'ranking', to_jsonb(public.battle_rank(p_battle.seed, n, k1, k2, k3)));
end;
$$;

-- ---------------------------------------------------------------------------
-- D. What the client sees of a round beyond the quiz fields
-- ---------------------------------------------------------------------------
create or replace function public.battle_round_extra(p_battle public.battles, p_round integer, p_viewer uuid,
                                                     p_slot integer, p_closed boolean, p_eval jsonb)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  g jsonb := p_battle.params -> 'game';
  q jsonb := p_battle.plan -> 'questions' -> p_round;
begin
  if p_battle.kind = 'vault' then
    return jsonb_build_object(
      'digits', (g ->> 'digits')::integer, 'symbols', (g ->> 'symbols')::integer,
      'guesses', coalesce((select jsonb_agg(jsonb_build_object('code', x.code, 'hits', x.hits, 'near', x.near) order by x.n)
                             from public.battle_guesses x
                            where x.battle_id = p_battle.id and x.round = p_round and x.player_id = p_viewer), '[]'::jsonb),
      'progress', coalesce((select jsonb_agg(jsonb_build_object(
                              'slot', p.slot,
                              'tries', (select count(*) from public.battle_guesses x
                                         where x.battle_id = p_battle.id and x.round = p_round and x.player_id = p.player_id),
                              'cracked', exists (select 1 from public.battle_answers x
                                                  where x.battle_id = p_battle.id and x.round = p_round
                                                    and x.player_id = p.player_id and x.answered_at is not null))
                              order by p.slot)
                             from public.battle_players p where p.battle_id = p_battle.id and p.slot is not null), '[]'::jsonb),
      'code', case when p_closed then q ->> 'code' end);
  elsif p_battle.kind = 'higher' then
    return jsonb_build_object('chart', (select jsonb_agg(round(x::numeric / 100, 2) order by o)
                                          from jsonb_array_elements_text(p_battle.plan -> 'series') with ordinality s(x, o)
                                         where o <= (g ->> 'history')::integer + p_round + 1));
  elsif p_battle.kind = 'auction' then
    return jsonb_build_object('item_points', (q ->> 'points')::integer, 'icon', q ->> 'icon',
                              'budget', case when p_slot is not null then p_eval -> 'budget' -> p_slot end,
                              'budgets', p_eval -> 'budget');
  end if;
  return '{}'::jsonb;
end;
$$;

-- ---------------------------------------------------------------------------
-- E. Answers: checked here, after battle_answer checked the battle, the player and the open round
-- ---------------------------------------------------------------------------
create or replace function public.battle_answer_more(p_battle public.battles, p_player uuid, p_slot integer,
                                                     p_round integer, p_choice integer, p_value numeric,
                                                     p_now timestamptz)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  g       jsonb := p_battle.params -> 'game';
  v_code  text;
  v_guess text;
  v_tries integer;
  v_hits  integer := 0;
  v_near  integer := 0;
  v_eval  jsonb;
  k       integer;
begin
  if p_battle.kind = 'vault' then
    v_guess := p_choice::text;
    if p_choice is null or p_choice <= 0
       or v_guess !~ ('^[1-' || (g ->> 'symbols') || ']{' || (g ->> 'digits') || '}$')
       or (select count(distinct c) from regexp_split_to_table(v_guess, '') c) <> (g ->> 'digits')::integer then
      perform public.api_error('invalid_argument');
    end if;
    -- one try after the other per player
    perform 1 from public.battle_players x where x.battle_id = p_battle.id and x.player_id = p_player for update;
    if exists (select 1 from public.battle_answers x where x.battle_id = p_battle.id and x.round = p_round
                  and x.player_id = p_player and x.answered_at is not null) then
      perform public.api_error('battle_round_closed');
    end if;
    select count(*)::integer into v_tries from public.battle_guesses x
     where x.battle_id = p_battle.id and x.round = p_round and x.player_id = p_player;
    if v_tries >= (g ->> 'maxTries')::integer then
      perform public.api_error('battle_round_closed');
    end if;
    v_code := p_battle.plan -> 'questions' -> p_round ->> 'code';
    for k in 1 .. char_length(v_guess) loop
      if substr(v_guess, k, 1) = substr(v_code, k, 1) then v_hits := v_hits + 1;
      elsif position(substr(v_guess, k, 1) in v_code) > 0 then v_near := v_near + 1;
      end if;
    end loop;
    insert into public.battle_guesses (battle_id, round, player_id, n, code, hits, near, guessed_at)
    values (p_battle.id, p_round, p_player, v_tries + 1, v_guess, v_hits, v_near, p_now);
    if v_hits = char_length(v_code) then
      insert into public.battle_answers (battle_id, round, player_id, choice, answered_at)
      values (p_battle.id, p_round, p_player, v_tries + 1, p_now)
      on conflict (battle_id, round, player_id) do nothing;
    end if;
    return;
  end if;
  if p_battle.kind = 'ticker' and (p_choice is null or p_choice < 0 or p_choice >= (g ->> 'options')::integer) then
    perform public.api_error('invalid_argument');
  end if;
  if p_battle.kind = 'higher' and (p_choice is null or p_choice not in (0, 1)) then
    perform public.api_error('invalid_argument');
  end if;
  if p_battle.kind = 'auction' then
    if p_value is null or p_value < 0 or p_value <> trunc(p_value) then
      perform public.api_error('invalid_argument');
    end if;
    -- never more than what is left
    v_eval := public.battle_rounds_eval_more(p_battle, p_now);
    if p_value > coalesce((v_eval -> 'budget' ->> p_slot)::integer, 0) then
      perform public.api_error('invalid_argument');
    end if;
  end if;
  insert into public.battle_answers (battle_id, round, player_id, choice, value_e4, answered_at)
  values (p_battle.id, p_round, p_player, case when p_battle.kind <> 'auction' then p_choice end,
          case when p_battle.kind = 'auction' then (p_value * 10000)::bigint end, p_now)
  on conflict (battle_id, round, player_id) do update
     set choice = excluded.choice, value_e4 = excluded.value_e4, answered_at = excluded.answered_at
   where public.battle_answers.answered_at is null;
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Wiring into the round games of 4720 (patched by replace, so other patches of these functions stay)
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text;
begin
  -- the plan
  v_def := pg_get_functiondef('public.battle_plan(text, jsonb)'::regprocedure);
  if position('battle_plan_more' in v_def) = 0 then
    v_def := replace(v_def, $q$begin
  if p_kind = 'quiz' then$q$, $q$begin
  if p_kind in ('vault', 'ticker', 'higher', 'auction') then
    return public.battle_plan_more(p_kind, p_params);
  end if;
  if p_kind = 'quiz' then$q$);
    if position('battle_plan_more' in v_def) = 0 then
      raise exception 'battle_plan() has an unexpected shape; add the new round games by hand';
    end if;
    execute v_def;
  end if;
  -- the timing: like the quiz
  v_def := pg_get_functiondef('public.battle_round_ms(public.battles, integer)'::regprocedure);
  if position('''auction''' in v_def) = 0 then
    v_def := replace(v_def, $q$if p_battle.kind in ('quiz', 'estimate') then$q$,
                     $q$if p_battle.kind in ('quiz', 'estimate', 'vault', 'ticker', 'higher', 'auction') then$q$);
    if position('''auction''' in v_def) = 0 then
      raise exception 'battle_round_ms() has an unexpected shape; add the new round games by hand';
    end if;
    execute v_def;
  end if;
  -- the judging
  v_def := pg_get_functiondef('public.battle_rounds_eval(public.battles, timestamptz)'::regprocedure);
  if position('battle_rounds_eval_more' in v_def) = 0 then
    v_def := replace(v_def, $q$begin
  select count(*)::integer into n from public.battle_players p where p.battle_id = p_battle.id and p.slot is not null;
  v_rounds := case v_kind when 'bell'$q$, $q$begin
  if v_kind in ('vault', 'ticker', 'higher', 'auction') then
    return public.battle_rounds_eval_more(p_battle, p_now);
  end if;
  select count(*)::integer into n from public.battle_players p where p.battle_id = p_battle.id and p.slot is not null;
  v_rounds := case v_kind when 'bell'$q$);
    if position('battle_rounds_eval_more' in v_def) = 0 then
      raise exception 'battle_rounds_eval() has an unexpected shape; add the new round games by hand';
    end if;
    execute v_def;
  end if;
  -- what the client sees
  v_def := pg_get_functiondef('public.battle_rounds_json(public.battles, uuid, timestamptz)'::regprocedure);
  if position('battle_round_extra' in v_def) = 0 then
    v_def := replace(v_def, $q$    if r < jsonb_array_length(v_eval -> 'results') then$q$,
                     $q$    v_item := v_item || public.battle_round_extra(p_battle, r, p_viewer, v_slot, v_ms >= t[2], v_eval);
    if r < jsonb_array_length(v_eval -> 'results') then$q$);
    if position('battle_round_extra' in v_def) = 0 then
      raise exception 'battle_rounds_json() has an unexpected shape; add the new round games by hand';
    end if;
    execute v_def;
  end if;
  -- the answers
  v_def := pg_get_functiondef('public.battle_answer(uuid, bigint, integer, integer, numeric)'::regprocedure);
  if position('battle_answer_more' in v_def) = 0 then
    v_def := replace(v_def, $q$  if b.kind = 'quiz' and (p_choice is null or p_choice < 0 or p_choice > 3) then$q$,
                     $q$  if b.kind in ('vault', 'ticker', 'higher', 'auction') then
    perform public.battle_answer_more(b, v_player, p.slot, p_round, p_choice, p_value, v_now);
    return public.request_complete(v_player, p_request_id, public.battle_state(v_player, v_now));
  end if;
  if b.kind = 'quiz' and (p_choice is null or p_choice < 0 or p_choice > 3) then$q$);
    if position('battle_answer_more' in v_def) = 0 then
      raise exception 'battle_answer() has an unexpected shape; add the new round games by hand';
    end if;
    execute v_def;
  end if;
end;
$do$;

do $do$
declare
  f text;
begin
  foreach f in array array[
    'public.battle_plan_more(text, jsonb)', 'public.battle_rounds_eval_more(public.battles, timestamptz)',
    'public.battle_round_extra(public.battles, integer, uuid, integer, boolean, jsonb)',
    'public.battle_answer_more(public.battles, uuid, integer, integer, integer, numeric, timestamptz)',
    'public.battle_plan(text, jsonb)', 'public.battle_round_ms(public.battles, integer)',
    'public.battle_rounds_eval(public.battles, timestamptz)', 'public.battle_rounds_json(public.battles, uuid, timestamptz)']
  loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
  end loop;
  execute 'revoke all on function public.battle_answer(uuid, bigint, integer, integer, numeric) from public, anon';
  execute 'grant execute on function public.battle_answer(uuid, bigint, integer, integer, numeric) to authenticated';
end;
$do$;

-- ===== supabase/updates/20261204005000_nft_market_livelier.sql =====
-- ===== idempotent copy of migrations/20261204005000_nft_market_livelier.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 5000 · A livelier NFT market: several collectors bid at once (ADR-163)
-- =============================================================================
-- Until now an NFT got a new AI offer only while no collector had an open one, so with offers open for a day a
-- player NFT saw at most one AI offer a day. Now up to nfts.ai.maxOpenAiOffers (3) different collectors may have an
-- open offer on the same NFT; a collector who already bids on it is not picked again. More activity comes from
-- game_config (higher offer and trade chances, more trades per run and day).
-- Idempotent: runs unchanged as supabase/updates/20261204005000_nft_market_livelier.sql.

-- a collector without an open offer on this NFT (null when all of them bid already)
create or replace function public.nft_free_collector(p_artwork uuid, p_u double precision)
returns text
language sql
stable
security definer
set search_path = ''
as $$
  select c from jsonb_array_elements_text(public.nfts_cfg() #> '{ai,collectors}') with ordinality t(c, ord)
   where not exists (select 1 from public.artwork_messages m where m.artwork_id = p_artwork and m.ai_name = c
                       and m.offer_status = 'open')
   order by abs(ord - 1 - floor(greatest(p_u, 0) * jsonb_array_length(public.nfts_cfg() #> '{ai,collectors}'))), ord
   limit 1;
$$;
revoke all on function public.nft_free_collector(uuid, double precision) from public, anon, authenticated;
grant execute on function public.nft_free_collector(uuid, double precision) to service_role;

do $do$
declare
  v_def text := pg_get_functiondef('public.nfts_run_due(timestamptz)'::regprocedure);
  -- 1. listed NFTs above the value: up to maxOpenAiOffers collectors, each picked among those without an offer
  v_old1 text := $t$          and not exists (select 1 from public.artwork_messages m where m.artwork_id = a.id and m.ai_name is not null
                            and m.offer_status = 'open') then
      v_id := public.nft_ai_post(a.id, public.nft_pick('{ai,collectors}', random()), 'offer',$t$;
  v_new1 text := $t$          and (select count(*) from public.artwork_messages m where m.artwork_id = a.id and m.ai_name is not null
                 and m.offer_status = 'open') < coalesce((ai ->> 'maxOpenAiOffers')::integer, 1)
          and public.nft_free_collector(a.id, random()) is not null then
      v_id := public.nft_ai_post(a.id, public.nft_free_collector(a.id, random()), 'offer',$t$;
  -- 2. NFTs players keep: the same
  v_old2 text := $t$              and not exists (select 1 from public.artwork_messages m where m.artwork_id = x.id and m.ai_name is not null
                                and m.offer_status = 'open')
            order by random() limit greatest(0, (ai ->> 'maxMessagesPerRun')::integer - v_msgs) loop
    continue when random() * 10000 >= (ai ->> 'unlistedOfferChanceBps')::integer;
    v_id := public.nft_ai_post(r.id, public.nft_pick('{ai,collectors}', random()), 'offer',$t$;
  v_new2 text := $t$              and (select count(*) from public.artwork_messages m where m.artwork_id = x.id and m.ai_name is not null
                     and m.offer_status = 'open') < coalesce((ai ->> 'maxOpenAiOffers')::integer, 1)
            order by random() limit greatest(0, (ai ->> 'maxMessagesPerRun')::integer - v_msgs) loop
    continue when random() * 10000 >= (ai ->> 'unlistedOfferChanceBps')::integer;
    continue when public.nft_free_collector(r.id, 0.5) is null;
    v_id := public.nft_ai_post(r.id, public.nft_free_collector(r.id, random()), 'offer',$t$;
begin
  if position('nft_free_collector' in v_def) = 0 then
    if position(v_old1 in v_def) = 0 or position(v_old2 in v_def) = 0 then
      raise exception 'nfts_run_due() has an unexpected shape; add the multi-collector offers by hand';
    end if;
    execute replace(replace(v_def, v_old1, v_new1), v_old2, v_new2);
  end if;
end;
$do$;

-- ===== supabase/updates/20261204005100_friend_chats.sql =====
-- ===== idempotent copy of migrations/20261204005100_friend_chats.sql =====
-- (the migration itself is written idempotently; keep both files identical below this line)
-- =============================================================================
-- NEXA · 5100 · Chats with friends: direct chats and groups (ADR-164)
-- =============================================================================
-- * friend_chats (direct or group), friend_chat_members (admin flag, last read message, first visible message) and
--   friend_chat_messages (player or system lines). Internal tables: read and written only by the RPCs below.
-- * Direct chats only between accepted friends; when the friendship ends the chat stays readable but read-only.
-- * Groups: a name (social.chat.groupName*, profanity filter), social.chat.groupMinMembers to groupMaxMembers members
--   including the creator, who is the admin. Every member may add own friends; the admin removes members and renames.
--   Who leaves last closes the group; when the admin leaves, the longest member takes over.
-- * Messages: social.chat.maxMessageLength characters, social.chat.maxMessagesPerMinute, profanity filter.
-- * Notification friend_chat for the other members, at most one unread per chat (like the company chat).
-- * Missions: metric friend_chat (own trigger), quick and daily templates, mission_doable() needs a friend.
-- * Errors: chat_unknown NX157, chat_read_only NX158, chat_not_admin NX159, chat_group_full NX160,
--   chat_group_too_small NX161, chat_already_member NX162.
-- Idempotent: runs unchanged as supabase/updates/20261204005100_friend_chats.sql.

-- ---------------------------------------------------------------------------
-- A. Error keys, notification type
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.api_error(text)'::regprocedure);
begin
  if position('''chat_already_member''' in v_def) = 0 then
    v_def := replace(v_def, $q$    when 'battle_unknown'             then 'NX156'
$q$, $q$    when 'battle_unknown'             then 'NX156'
    when 'chat_unknown'               then 'NX157'
    when 'chat_read_only'             then 'NX158'
    when 'chat_not_admin'             then 'NX159'
    when 'chat_group_full'            then 'NX160'
    when 'chat_group_too_small'       then 'NX161'
    when 'chat_already_member'        then 'NX162'
$q$);
    if position('''chat_already_member''' in v_def) = 0 then
      raise exception 'api_error() has an unexpected shape; add the chat error keys by hand';
    end if;
    execute v_def;
  end if;
end;
$do$;

insert into public.notification_types (key, category, title, description, icon_key, default_in_app, default_push, is_mandatory,
                                       sort_order)
values ('friend_chat', 'social', 'Chat mit Freunden', 'Ein Freund oder eine Gruppe hat dir geschrieben.',
        'notif_friend', true, true, false, 277)
on conflict (key) do nothing;

-- ---------------------------------------------------------------------------
-- B. Tables (internal)
-- ---------------------------------------------------------------------------
create table if not exists public.friend_chats (
  id              bigint generated always as identity primary key,
  kind            text not null check (kind in ('direct', 'group')),
  name            text check (name is null or char_length(name) between 1 and 64),
  -- direct chats: "<smaller uuid>:<bigger uuid>", one chat per pair
  direct_key      text unique,
  created_by      uuid references public.profiles (id) on delete set null,
  created_at      timestamptz not null default now(),
  last_message_at timestamptz not null default now(),
  check ((kind = 'direct') = (direct_key is not null)),
  check ((kind = 'group') = (name is not null))
);
create index if not exists friend_chats_created_by_idx on public.friend_chats (created_by, created_at desc);
alter table public.friend_chats enable row level security;
revoke all on public.friend_chats from public, anon, authenticated;
grant all on public.friend_chats to service_role;
comment on table public.friend_chats is
  'Chats between friends (ADR-164): direct (one per pair) or group with a name. Internal (RPCs get_chats, get_chat, ...).';

create table if not exists public.friend_chat_members (
  chat_id      bigint not null references public.friend_chats (id) on delete cascade,
  player_id    uuid not null references public.profiles (id) on delete cascade,
  is_admin     boolean not null default false,
  -- the newest message the member has seen; messages up to since_id stay hidden (added later to a group)
  last_read_id bigint not null default 0,
  since_id     bigint not null default 0,
  joined_at    timestamptz not null default now(),
  primary key (chat_id, player_id)
);
create index if not exists friend_chat_members_player_idx on public.friend_chat_members (player_id);
alter table public.friend_chat_members enable row level security;
revoke all on public.friend_chat_members from public, anon, authenticated;
grant all on public.friend_chat_members to service_role;
comment on table public.friend_chat_members is
  'Members of a friend chat (ADR-164) with admin flag and read marker. Internal.';

create table if not exists public.friend_chat_messages (
  id         bigint generated always as identity primary key,
  chat_id    bigint not null references public.friend_chats (id) on delete cascade,
  author_id  uuid references public.profiles (id) on delete cascade,
  kind       text not null default 'player' check (kind in ('player', 'system')),
  body       text not null check (char_length(body) between 1 and 500),
  created_at timestamptz not null default now()
);
create index if not exists friend_chat_messages_chat_idx on public.friend_chat_messages (chat_id, id desc);
create index if not exists friend_chat_messages_author_idx on public.friend_chat_messages (author_id, created_at desc);
alter table public.friend_chat_messages enable row level security;
revoke all on public.friend_chat_messages from public, anon, authenticated;
grant all on public.friend_chat_messages to service_role;
comment on table public.friend_chat_messages is
  'Messages of friend chats (ADR-164): player lines and system lines (joined, left, renamed). Internal.';

-- ---------------------------------------------------------------------------
-- C. Internal helpers
-- ---------------------------------------------------------------------------
create or replace function public.friend_chat_is_friend(p_a uuid, p_b uuid)
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
  select exists (select 1 from public.friendships f
                  where f.status = 'accepted'
                    and least(f.requester_id, f.addressee_id) = least(p_a, p_b)
                    and greatest(f.requester_id, f.addressee_id) = greatest(p_a, p_b));
$$;

create or replace function public.friend_chat_cfg(p_key text, p_default double precision)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select greatest(0, coalesce(public.config_double('social', array['chat', p_key], p_default), p_default))::integer;
$$;

-- unread player messages of one member (own lines and system lines do not count)
create or replace function public.friend_chat_unread(p_chat bigint, p_player uuid)
returns integer
language sql
stable
security definer
set search_path = ''
as $$
  select count(*)::integer
    from public.friend_chat_members cm
    join public.friend_chat_messages m on m.chat_id = cm.chat_id and m.id > greatest(cm.last_read_id, cm.since_id)
   where cm.chat_id = p_chat and cm.player_id = p_player and m.kind = 'player' and m.author_id is distinct from p_player;
$$;

create or replace function public.friend_chat_message_json(p_message bigint, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  select jsonb_build_object('id', m.id, 'kind', m.kind, 'author', p.nickname, 'avatar_key', p.avatar_key,
                            'is_me', m.author_id is not distinct from p_viewer and m.kind = 'player',
                            'body', m.body, 'created_at', m.created_at)
    from public.friend_chat_messages m left join public.profiles p on p.id = m.author_id
   where m.id = p_message;
$$;

-- the summary of a chat as one member sees it: the others, the last message, unread lines, rights
create or replace function public.friend_chat_json(p_chat bigint, p_viewer uuid)
returns jsonb
language sql
stable
security definer
set search_path = ''
as $$
  with me as (
    select cm.* from public.friend_chat_members cm where cm.chat_id = p_chat and cm.player_id = p_viewer
  ), others as (
    select cm.player_id, cm.is_admin, cm.joined_at, p.nickname, p.tag, p.level, p.avatar_key, p.last_active_at
      from public.friend_chat_members cm join public.profiles p on p.id = cm.player_id
     where cm.chat_id = p_chat and cm.player_id <> p_viewer
  ), last as (
    select m.id from public.friend_chat_messages m, me
     where m.chat_id = p_chat and m.id > me.since_id order by m.id desc limit 1
  )
  select jsonb_build_object(
    'id', c.id,
    'kind', c.kind,
    'name', case when c.kind = 'group' then c.name
                 else coalesce((select o.nickname from others o limit 1), '?') end,
    'is_admin', me.is_admin,
    'can_write', case when c.kind = 'group' then true
                      else exists (select 1 from others o where public.friend_chat_is_friend(p_viewer, o.player_id)) end,
    'unread', public.friend_chat_unread(p_chat, p_viewer),
    'member_count', 1 + (select count(*) from others),
    'members', coalesce((
      select jsonb_agg(jsonb_build_object(
               'nickname', o.nickname, 'tag', o.tag, 'level', o.level, 'avatar_key', o.avatar_key,
               'accessories', public.player_worn_accessories(o.player_id), 'is_admin', o.is_admin,
               'online', coalesce(o.last_active_at > public.game_now() - make_interval(
                           mins => coalesce(public.config_double('social', '{onlineMinutes}', 10), 10)::integer), false))
             order by o.is_admin desc, o.joined_at, lower(o.nickname))
        from others o), '[]'::jsonb),
    'last', (select public.friend_chat_message_json(l.id, p_viewer) from last l),
    'last_at', c.last_message_at)
    from public.friend_chats c, me
   where c.id = p_chat;
$$;

-- the member row of the caller, or chat_unknown (also for chats of others: no hint that they exist)
create or replace function public.friend_chat_require(p_chat bigint, p_player uuid)
returns public.friend_chats
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_chat public.friend_chats;
begin
  select c.* into v_chat from public.friend_chats c
   where c.id = p_chat and exists (select 1 from public.friend_chat_members cm where cm.chat_id = c.id and cm.player_id = p_player);
  if v_chat.id is null then
    perform public.api_error('chat_unknown');
  end if;
  return v_chat;
end;
$$;

-- a group name: trimmed, single spaces, social.chat.groupNameMinLength to groupNameMaxLength, no swear words
create or replace function public.friend_chat_name(p_name text)
returns text
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_name text := regexp_replace(btrim(coalesce(p_name, '')), '\s+', ' ', 'g');
begin
  if char_length(v_name) < public.friend_chat_cfg('groupNameMinLength', 3) then
    perform public.api_error('name_too_short');
  end if;
  if char_length(v_name) > public.friend_chat_cfg('groupNameMaxLength', 30) then
    perform public.api_error('name_too_long');
  end if;
  if v_name ~ '[[:cntrl:]<>]' then
    perform public.api_error('name_invalid_chars');
  end if;
  if public.text_has_profanity(v_name) or public.text_has_profanity(replace(v_name, ' ', '')) then
    perform public.api_error('name_profanity');
  end if;
  return v_name;
end;
$$;

create or replace function public.friend_chat_system(p_chat bigint, p_body text)
returns bigint
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id bigint;
begin
  insert into public.friend_chat_messages (chat_id, author_id, kind, body)
  values (p_chat, null, 'system', left(p_body, 500))
  returning id into v_id;
  update public.friend_chats set last_message_at = now() where id = p_chat;
  return v_id;
end;
$$;

-- tells the other members (or only p_only), at most one unread notification per chat and member
create or replace function public.friend_chat_notify(p_chat bigint, p_from uuid, p_body text, p_message bigint,
                                                     p_only uuid default null)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_chat public.friend_chats;
  v_nick text;
  r      record;
begin
  select c.* into v_chat from public.friend_chats c where c.id = p_chat;
  select p.nickname into v_nick from public.profiles p where p.id = p_from;
  for r in select cm.player_id from public.friend_chat_members cm
            where cm.chat_id = p_chat and cm.player_id <> p_from and (p_only is null or cm.player_id = p_only)
              and not exists (select 1 from public.notifications n
                               where n.player_id = cm.player_id and n.type_key = 'friend_chat' and n.read_at is null
                                 and n.payload ->> 'chat_id' = p_chat::text)
            order by cm.player_id loop
    perform public.social_notify(r.player_id, 'friend_chat',
      case when v_chat.kind = 'group' then 'Gruppe ' || v_chat.name else v_nick || ' hat dir geschrieben' end,
      case when v_chat.kind = 'group' then v_nick || ': ' else '' end
        || case when char_length(p_body) > 120 then left(p_body, 117) || '...' else p_body end,
      jsonb_build_object('chat_id', p_chat, 'message_id', p_message),
      '/friends?tab=chats&chat=' || p_chat::text, 'friend-chat:' || p_message::text);
  end loop;
end;
$$;

-- a member goes: the chat closes with the last one, the longest member becomes admin when none is left
create or replace function public.friend_chat_drop_member(p_chat bigint, p_player uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
begin
  delete from public.friend_chat_members where chat_id = p_chat and player_id = p_player;
  delete from public.notifications n
   where n.player_id = p_player and n.type_key = 'friend_chat' and n.read_at is null and n.payload ->> 'chat_id' = p_chat::text;
  if not exists (select 1 from public.friend_chat_members where chat_id = p_chat) then
    delete from public.friend_chats where id = p_chat;
  elsif not exists (select 1 from public.friend_chat_members where chat_id = p_chat and is_admin) then
    update public.friend_chat_members set is_admin = true
     where (chat_id, player_id) = (select cm.chat_id, cm.player_id from public.friend_chat_members cm
                                    where cm.chat_id = p_chat order by cm.joined_at, cm.player_id limit 1);
  end if;
end;
$$;

-- account reset: direct chats go, the player leaves every group, own lines are deleted
create or replace function public.friend_chats_wipe_player(p_player uuid)
returns void
language plpgsql
security definer
set search_path = ''
as $$
declare
  r record;
begin
  delete from public.friend_chats c
   where c.kind = 'direct'
     and exists (select 1 from public.friend_chat_members cm where cm.chat_id = c.id and cm.player_id = p_player);
  delete from public.friend_chat_messages where author_id = p_player;
  for r in select cm.chat_id from public.friend_chat_members cm where cm.player_id = p_player order by cm.chat_id loop
    perform public.friend_chat_drop_member(r.chat_id, p_player);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- D. RPCs
-- ---------------------------------------------------------------------------
create or replace function public.get_chats()
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_chats  jsonb;
begin
  v_player := public.require_player();
  select coalesce(jsonb_agg(public.friend_chat_json(c.id, v_player) order by c.last_message_at desc, c.id desc), '[]'::jsonb)
    into v_chats
    from (select c.id, c.last_message_at
            from public.friend_chats c join public.friend_chat_members cm on cm.chat_id = c.id and cm.player_id = v_player
           -- an opened direct chat without a line shows only for who opened it
           where c.kind = 'group' or c.created_by = v_player
              or exists (select 1 from public.friend_chat_messages m where m.chat_id = c.id and m.kind = 'player')
           order by c.last_message_at desc, c.id desc
           limit 100) c;
  return jsonb_build_object('chats', v_chats,
                            'unread', coalesce((select sum((x ->> 'unread')::integer) from jsonb_array_elements(v_chats) x), 0));
end;
$$;
comment on function public.get_chats() is
  'RPC: the own friend chats, newest first, with members, last message and unread lines (ADR-164).';

create or replace function public.get_chat(p_chat_id bigint, p_before_id bigint default null)
returns jsonb
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_since  bigint;
  v_page   integer := greatest(1, public.friend_chat_cfg('pageSize', 50));
  v_rows   jsonb;
  v_count  integer;
begin
  v_player := public.require_player();
  perform public.friend_chat_require(p_chat_id, v_player);
  select cm.since_id into v_since from public.friend_chat_members cm where cm.chat_id = p_chat_id and cm.player_id = v_player;
  select coalesce(jsonb_agg(public.friend_chat_message_json(x.id, v_player) order by x.id), '[]'::jsonb), count(*)
    into v_rows, v_count
    from (select m.id from public.friend_chat_messages m
           where m.chat_id = p_chat_id and m.id > v_since and (p_before_id is null or m.id < p_before_id)
           order by m.id desc limit v_page + 1) x;
  if v_count > v_page then
    v_rows := v_rows - 0;
  end if;
  return jsonb_build_object('chat', public.friend_chat_json(p_chat_id, v_player), 'messages', v_rows,
                            'has_more', v_count > v_page);
end;
$$;
comment on function public.get_chat(bigint, bigint) is
  'RPC: one friend chat with its newest messages (older ones with p_before_id), oldest first (ADR-164). Error chat_unknown.';

create or replace function public.mark_chat_read(p_chat_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
begin
  v_player := public.require_player();
  perform public.friend_chat_require(p_chat_id, v_player);
  update public.friend_chat_members cm
     set last_read_id = greatest(cm.last_read_id,
                                 coalesce((select max(m.id) from public.friend_chat_messages m where m.chat_id = p_chat_id), 0))
   where cm.chat_id = p_chat_id and cm.player_id = v_player;
  update public.notifications n set read_at = now()
   where n.player_id = v_player and n.type_key = 'friend_chat' and n.read_at is null
     and n.payload ->> 'chat_id' = p_chat_id::text;
  return jsonb_build_object('unread', coalesce((select sum(public.friend_chat_unread(cm.chat_id, v_player))
                                                  from public.friend_chat_members cm where cm.player_id = v_player), 0));
end;
$$;
comment on function public.mark_chat_read(bigint) is
  'RPC: marks a friend chat as read (and its notification); idempotent, returns all unread lines (ADR-164).';

create or replace function public.open_direct_chat(p_request_id uuid, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_other  uuid;
  v_key    text;
  v_chat   bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'open_direct_chat');
  if v_replay is not null then
    return v_replay;
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  if not public.friend_chat_is_friend(v_player, v_other) then
    perform public.api_error('not_friends');
  end if;
  v_key := least(v_player, v_other)::text || ':' || greatest(v_player, v_other)::text;
  insert into public.friend_chats (kind, direct_key, created_by) values ('direct', v_key, v_player)
  on conflict (direct_key) do nothing;
  select c.id into v_chat from public.friend_chats c where c.direct_key = v_key;
  insert into public.friend_chat_members (chat_id, player_id) values (v_chat, v_player), (v_chat, v_other)
  on conflict do nothing;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('chat', public.friend_chat_json(v_chat, v_player)));
end;
$$;
comment on function public.open_direct_chat(uuid, text) is
  'RPC: the direct chat with a friend, created on first use (ADR-164). Errors not_friends, player_not_found.';

create or replace function public.create_group_chat(p_request_id uuid, p_name text, p_nicknames text[])
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_name   text;
  v_ids    uuid[] := '{}';
  v_id     uuid;
  v_nick   text;
  v_chat   bigint;
  v_msg    bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'create_group_chat');
  if v_replay is not null then
    return v_replay;
  end if;
  v_name := public.friend_chat_name(p_name);
  if coalesce(cardinality(p_nicknames), 0) > 100 then
    perform public.api_error('chat_group_full');
  end if;
  foreach v_nick in array coalesce(p_nicknames, '{}') loop
    v_id := public.friend_target(v_player, v_nick);
    if not public.friend_chat_is_friend(v_player, v_id) then
      perform public.api_error('not_friends');
    end if;
    if not v_id = any (v_ids) then
      v_ids := v_ids || v_id;
    end if;
  end loop;
  if cardinality(v_ids) + 1 < greatest(2, public.friend_chat_cfg('groupMinMembers', 2)) then
    perform public.api_error('chat_group_too_small');
  end if;
  if cardinality(v_ids) + 1 > public.friend_chat_cfg('groupMaxMembers', 20) then
    perform public.api_error('chat_group_full');
  end if;
  -- one creation at a time per player; a few groups a day at most
  perform 1 from public.profiles p where p.id = v_player for update;
  if (select count(*) from public.friend_chats c where c.created_by = v_player and c.kind = 'group'
         and c.created_at > now() - interval '24 hours') >= public.friend_chat_cfg('maxGroupsPerDay', 10) then
    perform public.api_error('rate_limited');
  end if;
  insert into public.friend_chats (kind, name, created_by) values ('group', v_name, v_player) returning id into v_chat;
  insert into public.friend_chat_members (chat_id, player_id, is_admin) values (v_chat, v_player, true);
  insert into public.friend_chat_members (chat_id, player_id) select v_chat, x from unnest(v_ids) x;
  select p.nickname into v_nick from public.profiles p where p.id = v_player;
  v_msg := public.friend_chat_system(v_chat, v_nick || ' hat die Gruppe „' || v_name || '“ gegründet.');
  update public.friend_chat_members set last_read_id = v_msg where chat_id = v_chat and player_id = v_player;
  perform public.friend_chat_notify(v_chat, v_player, v_nick || ' hat dich in die Gruppe geholt.', v_msg);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('chat', public.friend_chat_json(v_chat, v_player)));
end;
$$;
comment on function public.create_group_chat(uuid, text, text[]) is
  'RPC: a group chat with own friends, the caller is admin (ADR-164). Errors name_*, not_friends, chat_group_too_small, '
  'chat_group_full, rate_limited.';

create or replace function public.post_chat_message(p_request_id uuid, p_chat_id bigint, p_body text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_chat   public.friend_chats;
  v_body   text := btrim(coalesce(p_body, ''));
  v_id     bigint;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'post_chat_message');
  if v_replay is not null then
    return v_replay;
  end if;
  v_chat := public.friend_chat_require(p_chat_id, v_player);
  if v_chat.kind = 'direct' and not exists (
       select 1 from public.friend_chat_members cm
        where cm.chat_id = v_chat.id and cm.player_id <> v_player and public.friend_chat_is_friend(v_player, cm.player_id)) then
    perform public.api_error('chat_read_only');
  end if;
  if v_body = '' or char_length(v_body) > public.friend_chat_cfg('maxMessageLength', 300) then
    perform public.api_error('invalid_argument');
  end if;
  if public.text_has_profanity(v_body) then
    perform public.api_error('name_profanity');
  end if;
  perform 1 from public.profiles p where p.id = v_player for update;
  if (select count(*) from public.friend_chat_messages m
       where m.author_id = v_player and m.kind = 'player' and m.created_at > now() - interval '1 minute')
     >= public.friend_chat_cfg('maxMessagesPerMinute', 12) then
    perform public.api_error('rate_limited');
  end if;
  insert into public.friend_chat_messages (chat_id, author_id, kind, body) values (v_chat.id, v_player, 'player', v_body)
  returning id into v_id;
  update public.friend_chats set last_message_at = now() where id = v_chat.id;
  update public.friend_chat_members set last_read_id = v_id where chat_id = v_chat.id and player_id = v_player;
  perform public.friend_chat_notify(v_chat.id, v_player, v_body, v_id);
  return public.request_complete(v_player, p_request_id,
                                 jsonb_build_object('message', public.friend_chat_message_json(v_id, v_player)));
end;
$$;
comment on function public.post_chat_message(uuid, bigint, text) is
  'RPC: writes into a friend chat (ADR-164). Errors chat_unknown, chat_read_only, invalid_argument, name_profanity, rate_limited.';

create or replace function public.add_group_member(p_request_id uuid, p_chat_id bigint, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_chat   public.friend_chats;
  v_other  uuid;
  v_since  bigint;
  v_msg    bigint;
  v_me     text;
  v_them   text;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'add_group_member');
  if v_replay is not null then
    return v_replay;
  end if;
  v_chat := public.friend_chat_require(p_chat_id, v_player);
  if v_chat.kind <> 'group' then
    perform public.api_error('invalid_argument');
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  if not public.friend_chat_is_friend(v_player, v_other) then
    perform public.api_error('not_friends');
  end if;
  perform 1 from public.friend_chats c where c.id = v_chat.id for update;
  if exists (select 1 from public.friend_chat_members cm where cm.chat_id = v_chat.id and cm.player_id = v_other) then
    perform public.api_error('chat_already_member');
  end if;
  if (select count(*) from public.friend_chat_members cm where cm.chat_id = v_chat.id)
     >= public.friend_chat_cfg('groupMaxMembers', 20) then
    perform public.api_error('chat_group_full');
  end if;
  select coalesce(max(m.id), 0) into v_since from public.friend_chat_messages m where m.chat_id = v_chat.id;
  insert into public.friend_chat_members (chat_id, player_id, since_id, last_read_id) values (v_chat.id, v_other, v_since, v_since);
  select p.nickname into v_me from public.profiles p where p.id = v_player;
  select p.nickname into v_them from public.profiles p where p.id = v_other;
  v_msg := public.friend_chat_system(v_chat.id, v_me || ' hat ' || v_them || ' hinzugefügt.');
  perform public.friend_chat_notify(v_chat.id, v_player, v_me || ' hat dich in die Gruppe geholt.', v_msg, v_other);
  return public.request_complete(v_player, p_request_id, jsonb_build_object('chat', public.friend_chat_json(v_chat.id, v_player)));
end;
$$;
comment on function public.add_group_member(uuid, bigint, text) is
  'RPC: a member adds an own friend to a group (ADR-164). Errors chat_unknown, not_friends, chat_already_member, chat_group_full.';

create or replace function public.remove_group_member(p_request_id uuid, p_chat_id bigint, p_nickname text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_chat   public.friend_chats;
  v_other  uuid;
  v_me     text;
  v_them   text;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'remove_group_member');
  if v_replay is not null then
    return v_replay;
  end if;
  v_chat := public.friend_chat_require(p_chat_id, v_player);
  if v_chat.kind <> 'group' then
    perform public.api_error('invalid_argument');
  end if;
  if not exists (select 1 from public.friend_chat_members cm where cm.chat_id = v_chat.id and cm.player_id = v_player and cm.is_admin) then
    perform public.api_error('chat_not_admin');
  end if;
  v_other := public.friend_target(v_player, p_nickname);
  if not exists (select 1 from public.friend_chat_members cm where cm.chat_id = v_chat.id and cm.player_id = v_other) then
    perform public.api_error('player_not_found');
  end if;
  select p.nickname into v_me from public.profiles p where p.id = v_player;
  select p.nickname into v_them from public.profiles p where p.id = v_other;
  perform public.friend_chat_drop_member(v_chat.id, v_other);
  perform public.friend_chat_system(v_chat.id, v_me || ' hat ' || v_them || ' aus der Gruppe genommen.');
  return public.request_complete(v_player, p_request_id, jsonb_build_object('chat', public.friend_chat_json(v_chat.id, v_player)));
end;
$$;
comment on function public.remove_group_member(uuid, bigint, text) is
  'RPC: the admin removes a member from a group (ADR-164). Errors chat_unknown, chat_not_admin, player_not_found.';

create or replace function public.leave_group(p_request_id uuid, p_chat_id bigint)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_chat   public.friend_chats;
  v_me     text;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'leave_group');
  if v_replay is not null then
    return v_replay;
  end if;
  v_chat := public.friend_chat_require(p_chat_id, v_player);
  if v_chat.kind <> 'group' then
    perform public.api_error('invalid_argument');
  end if;
  select p.nickname into v_me from public.profiles p where p.id = v_player;
  perform public.friend_chat_drop_member(v_chat.id, v_player);
  if exists (select 1 from public.friend_chats c where c.id = v_chat.id) then
    perform public.friend_chat_system(v_chat.id, v_me || ' hat die Gruppe verlassen.');
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('chat_id', v_chat.id, 'left', true));
end;
$$;
comment on function public.leave_group(uuid, bigint) is
  'RPC: leaves a group; the last one closes it, a new admin follows the old one (ADR-164). Error chat_unknown.';

create or replace function public.rename_group(p_request_id uuid, p_chat_id bigint, p_name text)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_player uuid;
  v_replay jsonb;
  v_chat   public.friend_chats;
  v_name   text;
  v_me     text;
begin
  v_player := public.require_player();
  if p_request_id is null then
    perform public.api_error('invalid_argument');
  end if;
  v_replay := public.request_begin(v_player, p_request_id, 'rename_group');
  if v_replay is not null then
    return v_replay;
  end if;
  v_chat := public.friend_chat_require(p_chat_id, v_player);
  if v_chat.kind <> 'group' then
    perform public.api_error('invalid_argument');
  end if;
  if not exists (select 1 from public.friend_chat_members cm where cm.chat_id = v_chat.id and cm.player_id = v_player and cm.is_admin) then
    perform public.api_error('chat_not_admin');
  end if;
  v_name := public.friend_chat_name(p_name);
  if v_name is distinct from v_chat.name then
    update public.friend_chats set name = v_name where id = v_chat.id;
    select p.nickname into v_me from public.profiles p where p.id = v_player;
    perform public.friend_chat_system(v_chat.id, v_me || ' hat die Gruppe in „' || v_name || '“ umbenannt.');
  end if;
  return public.request_complete(v_player, p_request_id, jsonb_build_object('chat', public.friend_chat_json(v_chat.id, v_player)));
end;
$$;
comment on function public.rename_group(uuid, bigint, text) is
  'RPC: the admin renames a group (ADR-164). Errors chat_unknown, chat_not_admin, name_*.';

-- ---------------------------------------------------------------------------
-- E. Grants
-- ---------------------------------------------------------------------------
do $$
declare
  f text;
begin
  foreach f in array array[
    'public.friend_chat_is_friend(uuid, uuid)', 'public.friend_chat_cfg(text, double precision)',
    'public.friend_chat_unread(bigint, uuid)', 'public.friend_chat_message_json(bigint, uuid)',
    'public.friend_chat_json(bigint, uuid)', 'public.friend_chat_require(bigint, uuid)', 'public.friend_chat_name(text)',
    'public.friend_chat_system(bigint, text)', 'public.friend_chat_notify(bigint, uuid, text, bigint, uuid)',
    'public.friend_chat_drop_member(bigint, uuid)', 'public.friend_chats_wipe_player(uuid)',
    'public.get_chats()', 'public.get_chat(bigint, bigint)', 'public.mark_chat_read(bigint)',
    'public.open_direct_chat(uuid, text)', 'public.create_group_chat(uuid, text, text[])',
    'public.post_chat_message(uuid, bigint, text)', 'public.add_group_member(uuid, bigint, text)',
    'public.remove_group_member(uuid, bigint, text)', 'public.leave_group(uuid, bigint)',
    'public.rename_group(uuid, bigint, text)'
  ] loop
    execute format('revoke all on function %s from public, anon, authenticated', f);
    execute format('grant execute on function %s to service_role', f);
  end loop;
  foreach f in array array[
    'public.get_chats()', 'public.get_chat(bigint, bigint)', 'public.mark_chat_read(bigint)',
    'public.open_direct_chat(uuid, text)', 'public.create_group_chat(uuid, text, text[])',
    'public.post_chat_message(uuid, bigint, text)', 'public.add_group_member(uuid, bigint, text)',
    'public.remove_group_member(uuid, bigint, text)', 'public.leave_group(uuid, bigint)',
    'public.rename_group(uuid, bigint, text)'
  ] loop
    execute format('grant execute on function %s to authenticated', f);
  end loop;
end;
$$;

-- ---------------------------------------------------------------------------
-- F. Account reset, missions
-- ---------------------------------------------------------------------------
do $do$
declare
  v_def text := pg_get_functiondef('public.account_wipe(uuid, text)'::regprocedure);
  v_old text := $t$  perform public.rentals_wipe_player(p_player);$t$;
  v_new text := $t$  perform public.rentals_wipe_player(p_player);

  -- friend chats (ADR-164): direct chats go, groups are left, own lines deleted
  perform public.friend_chats_wipe_player(p_player);$t$;
begin
  if position('friend_chats_wipe_player' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'account_wipe() has an unexpected shape; add friend_chats_wipe_player by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

do $do$
declare
  v_def text := pg_get_functiondef('public.mission_doable(uuid, text, text)'::regprocedure);
  v_old text := $t$    when p_metric = 'company_chat' then$t$;
  v_new text := $t$    -- ADR-164: writing to a friend needs a friend
    when p_metric = 'friend_chat' then exists (select 1 from public.friendships f
                                                where f.status = 'accepted' and p_player in (f.requester_id, f.addressee_id))
    when p_metric = 'company_chat' then$t$;
begin
  if position('''friend_chat''' in v_def) = 0 then
    if position(v_old in v_def) = 0 then
      raise exception 'mission_doable() has an unexpected shape; add friend_chat by hand';
    end if;
    execute replace(v_def, v_old, v_new);
  end if;
end;
$do$;

create or replace function public.friend_chat_mission_events()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.kind = 'player' and new.author_id is not null then
    perform public.mission_event(new.author_id, 'friend_chat', 1, new.chat_id::text);
  end if;
  return new;
end;
$$;
revoke all on function public.friend_chat_mission_events() from public, anon, authenticated;
comment on function public.friend_chat_mission_events() is 'Trigger: mission event friend_chat for every own line (ADR-164).';
drop trigger if exists mission_events on public.friend_chat_messages;
create trigger mission_events after insert on public.friend_chat_messages
  for each row execute function public.friend_chat_mission_events();

insert into public.mission_templates
  (key, kind, title, description, icon_key, metric, mode, params, target_min, target_max, xp_min, xp_max, min_level, chain_order,
   scale_with_level, weight, reward_skill_points)
values
  ('q_friend_chat', 'quick', 'Schreib einem Freund', 'Ein kurzes Hallo im Chat. Freunde freuen sich.', 'mission_bell', 'friend_chat', 'count', '{}'::jsonb, 1, 1, 25, 35, 1, 0, false, 40, 0),
  ('d_friend_chat', 'daily', 'Schreib {target} Nachrichten an Freunde', 'Tratsch über Kurse zählt auch.', 'mission_bell', 'friend_chat', 'count', '{}'::jsonb, 3, 5, 200, 280, 1, 0, true, 30, 0)
on conflict (key) do update
   set kind = excluded.kind, title = excluded.title, description = excluded.description, icon_key = excluded.icon_key,
       metric = excluded.metric, mode = excluded.mode, params = excluded.params, target_min = excluded.target_min,
       target_max = excluded.target_max, xp_min = excluded.xp_min, xp_max = excluded.xp_max, min_level = excluded.min_level,
       chain_order = excluded.chain_order, scale_with_level = excluded.scale_with_level, weight = excluded.weight,
       reward_skill_points = excluded.reward_skill_points, is_active = true, updated_at = now();

commit;
